def transform(grid):
    R, C = len(grid), len(grid[0])
    out = [[0] * C for _ in range(R)]
    cells = {(r, c) for r in range(R) for c in range(C) if grid[r][c] == 8}

    # Find an exact cover by 2x2 squares and L-triominoes.
    pieces = []
    for r in range(R - 1):
        for c in range(C - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            pieces.append((square, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4)]:
                pieces.append((square - {missing}, color))

    by_cell = {p: [] for p in cells}
    for shape, color in pieces:
        if shape <= cells:
            for p in shape:
                by_cell[p].append((shape, color))

    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda q: sum(shape <= left for shape, _ in by_cell[q]))
        for shape, color in by_cell[p]:
            if shape <= left:
                rest = solve(left - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    cover = solve(cells)
    if cover:
        for shape, color in cover:
            for r, c in shape:
                out[r][c] = color
    return out
